import sys; sys.path.insert(0,'.')
from cvlib import folds
d=np.load('base_reads.npz'); y=d['y']; R=np.load('reserved.npy')
keep=np.setdiff1d(np.arange(768),R)
M={j:d[f'mean_hidden_L{j}'][:,keep] for j in range(13)}
C={j:d[f'cls_hidden_L{j}'][:,keep] for j in range(13)}
def z(X): return (X-X.mean(0))/(X.std(0)+1e-6)
def kcv_scores(K, y, lam, seed):
    Y=np.eye(8)[y]; f=folds(y,5,seed); S=np.zeros((len(y),8))
    for i in range(5):
        tr=f!=i; te=f==i
        A=np.linalg.solve(K[np.ix_(tr,tr)]+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0))
        S[te]=K[np.ix_(te,tr)]@A
    return S
def nz(X): Z=z(X); return Z/np.linalg.norm(Z,axis=1,keepdims=True)
def linK(X): Z=z(X); return Z@Z.T
# start readout: linear ridge on z-scored concat, lam 300 -> kernel form ZZ^T, lam 300
Xs=np.hstack([M[2],M[6],M[10],C[12]])
Ks=linK(Xs)
Lk={j:z(M[j])@z(M[j]).T/M[j].shape[1] for j in range(10)}
cands={}
for top,lins in [(8,(2,6)),(8,(2,)),(9,(2,)),(9,(2,6))]:
    Zt=nz(M[top]); Q=Zt@Zt.T
    cands[(top,lins)]=Q+Q**2+sum(Lk[j] for j in lins)
for lam in (100,300,1000):
    print('start lam',lam,[round(100*(kcv_scores(Ks,y,lam,s).argmax(1)==y).mean(),2) for s in (0,1,2)])
for s in (0,1,2):
    ps=kcv_scores(Ks,y,300,s).argmax(1)
    for k,K in cands.items():
        pc=kcv_scores(K,y,1e-2,s).argmax(1)
        print(s,k,'start err',(ps!=y).sum(),'cand err',(pc!=y).sum(),'cand-only wrong',((pc!=y)&(ps==y)).sum(),'start-only wrong',((ps!=y)&(pc==y)).sum())
